window.onload=function(){
    let canvasElem = document.querySelector("canvas");
    canvasElem.addEventListener('mousedown', function(e) {
        getCursorPosition(canvasElem, e)
    });
}    
function getCursorPosition(canvas, event) {
    var ctx = canvas.getContext("2d");
    const rect = canvas.getBoundingClientRect()
    const x = event.clientX - rect.left
    const y = event.clientY - rect.top
    
    //alert("x:"+x+";y:"+y);

    for(j=0;j<x_camaras_global.length;j++){
        //alert("test:"+x_camaras_global[j]+"//"+y_camaras_global[j]);
        aux1=Math.abs(parseInt(x_camaras_global[j])-x);
        aux2=(Math.abs(parseInt(y_camaras_global[j])-y));
        //alert("distanciax:"+aux1+"//"+"distanciay:"+aux2);
        if(Math.abs(parseInt(x_camaras_global[j])-x)<10){
            if(Math.abs(parseInt(y_camaras_global[j])-y)<10){
                window.open("../images/"+accesos_global[j]+"_1.jpg");
                window.open("../images/"+accesos_global[j]+"_0.jpg");
            }
        }
    }
} 
